insert into public.events
  (slug, title, description, venue, starts_at, is_tentative, banner_url, registration_url, details, status)
select x.slug, x.title, x.description, x.venue, x.starts_at, x.is_tentative,
       x.banner_url, x.registration_url, x.details, 'published'
from jsonb_to_recordset($seed$[{"slug":"event-jjcc-2026","title":"Joint Journal Club Conference (JJCC)","description":"Presented by LAUMED Journal Club, the Joint Journal Club Conference (JJCC) is tentatively scheduled for 12 December 2026. This date is provisional and subject to confirmation; official venue, schedule, and registration announcements will follow.","venue":"To be announced","starts_at":"2026-12-12T08:00:00.000Z","is_tentative":true,"banner_url":"/assets/aistudio/photo_2026-11-13_00-03-24_6fae618f.jpg","registration_url":null,"details":{"subtitle":"Event Announcement · Presented by LAUMED Journal Club","theme":"Anticipate! — Presented by LAUMED Journal Club","displayDate":"12 December 2026 (Tentative — Subject to Confirmation)","time":"To be announced","registrationOpen":false,"labelsFor":"2026-12-12T08:00:00.000Z"}},{"slug":"event-webinar-2026","title":"Research Webinar Series","description":"A comprehensive virtual research training series hosted by LAUMED Journal Club via Google Meet, equipping medical students and early-career researchers with practical skills across literature searching, peer-reviewed publishing, systematic review methodology, and meta-analysis.","venue":"Google Meet","starts_at":"2026-09-12T17:00:00.000Z","is_tentative":false,"banner_url":"/assets/aistudio/photo_2026-11-13_00-03-29_b90ca4a5.jpg","registration_url":null,"details":{"subtitle":"LAUMED Journal Club Capacity Building Series","theme":"Research Questions, Journal Publishing, Review Methodology & Meta-Analysis","displayDate":"Saturday, 12th September, 2026","time":"6:00pm Prompt","registrationFee":"₦2,000","highlights":["Developing research questions and effective search strategies","Navigating journal publishing: selecting the right journal and responding to reviewer feedback","Writing the methodology section for scoping, systematic, and narrative reviews (including paper screening techniques)","Fundamentals of meta-analysis","From systematic review to meta-analysis: data extraction, effect sizes and statistical synthesis"],"speakers":[{"name":"Dr. Kehinde Paul","role":"Speaker"},{"name":"Dr. Samson Afolabi","role":"Speaker"},{"name":"Dr. Aderinto Nicholas","role":"Speaker"},{"name":"Godswill Uzoechina","role":"Speaker"}],"registrationOpen":false,"labelsFor":"2026-09-12T17:00:00.000Z"}},{"slug":"event-hackathon-paediatrics","title":"LAUMED Hackathon and Abstract Presentation","description":"An innovation hackathon and scholarly abstract presentation jointly presented by LAUMED Journal Club and Medificial Intelligence around the theme 'The Future of Paediatrics: Transforming child health through artificial intelligence.' Held at The Assembly by Ennovate Lab near LAUTECH Main Gate.","venue":"The Assembly by Ennovate Lab, beside Willows Nest Hotel along LAUTECH Main Gate","starts_at":"2026-04-18T08:00:00.000Z","is_tentative":false,"banner_url":"/assets/aistudio/photo_2026-11-13_00-11-56_48112b67.jpg","registration_url":null,"details":{"subtitle":"Presented by LAUMED Journal Club & Medificial Intelligence","theme":"THE FUTURE OF PAEDIATRICS: Transforming child health through artificial intelligence.","displayDate":"18th April","time":"9:00 AM","highlightsTitle":"Program Highlights","highlights":["The Pitch","Poster Presentation","Art and Science"],"judges":[{"name":"Prof. Tesleem Babatunde Asafa","title":"Professor of Mechanical Engineering, Ladoke Akintola University of Technology"},{"name":"Dr. Olanike Oladibu","title":"Consultant Pediatrician, LAUTECH Teaching Hospital, Ogbomoso"},{"name":"Mr. Afolabi Favour","title":"Mentor and Lead Instructor, SQI College of ICT"}],"sponsor":{"name":"Prof. Olawale Olakulehin","title":"Chief Medical Director, LAUTECH Teaching Hospital, Ogbomoso"},"registrationOpen":false,"labelsFor":"2026-04-18T08:00:00.000Z"}},{"slug":"event-launch-2025","title":"Medificial Intelligence Scientific Conference and Journal Launch","description":"Our flagship scientific conference and official launch of the Medificial Intelligence edition of LAUMED Journal at LAUTECH (100 slots capacity). Featured a keynote address on artificial intelligence in Nigeria's healthcare system, a four-member academic panel, and on-site distribution of LAUMED Journal membership forms.","venue":"The Hall, LAUTECH, Ogbomoso, Nigeria","starts_at":"2025-02-27T07:30:00.000Z","is_tentative":false,"banner_url":"/assets/aistudio/photo_2026-11-13_00-03-13_438c8629.jpg","registration_url":null,"details":{"subtitle":"Presented by LAUMED Journal Club & Medificial Intelligence","theme":"MEDIFICIAL INTELLIGENCE: REVOLUTIONIZING HEALTHCARE WITH TECHNOLOGY.","isFlagship":true,"displayDate":"27th February, 2025","time":"8:30 am GMT+1","registrationOpen":false,"recap":{"summary":"Presented by LAUMED Journal Club ('more is definitely better…') at The Hall, LAUTECH, Ogbomoso. The conference centered on the theme 'Medificial Intelligence: Revolutionizing Healthcare with Technology' and marked the launch of the themed journal edition alongside membership form distribution.","keynoteSpeaker":{"name":"Professor Oluwadiya Kehinde Sunday","title":"Acting Chief Medical Director of the University of Sierra Leone Teaching Hospitals Complex, Freetown","topic":"The Trajectory of Artificial Intelligence in Nigeria's Healthcare System; Exploring Options and Opportunities"},"panelists":[{"name":"Professor Michael Olamoyegun","affiliation":"Founder, The South West Diabetes Investigation Research Group (SWEDIG), Nigeria"},{"name":"Dr Mrs Oluyinka Titilayo Adedeji","affiliation":"Conference Panelist"},{"name":"Professor Adeseye Akintunde","affiliation":"Member, Editorial Board for the Current Hypertension Review Journal"},{"name":"Professor Justice","affiliation":"Director of the LAUTECH Software Engineering Institute"}],"reportDownloadUrl":"#download-conference-report-2025"},"labelsFor":"2025-02-27T07:30:00.000Z"}}]$seed$::jsonb)
  as x(slug text, title text, description text, venue text, starts_at timestamptz,
       is_tentative boolean, banner_url text, registration_url text, details jsonb)
on conflict (slug) do nothing;

insert into public.resources
  (legacy_id, title, organization, category, description, url, sort_order, status)
select x.legacy_id, x.title, x.organization, x.category, x.description, x.url, x.sort_order, 'published'
from jsonb_to_recordset($seed$[{"legacy_id":"res-casp-checklists","title":"CASP Critical Appraisal Checklists","organization":"Critical Appraisal Skills Programme","category":"Critical Appraisal","description":"Official suite of validated checklists for appraising RCTs, systematic reviews, cohort studies, diagnostic studies, case-control studies, and qualitative research.","url":"https://casp-uk.net/casp-tools-checklists/","sort_order":0},{"legacy_id":"res-jbi-tools","title":"JBI Critical Appraisal Tools","organization":"Joanna Briggs Institute","category":"Critical Appraisal","description":"Comprehensive evidence appraisal checklists covering analytical cross-sectional studies, case reports, quasi-experimental designs, RCTs, and prevalence studies.","url":"https://jbi.global/critical-appraisal-tools","sort_order":1},{"legacy_id":"res-prisma-2020","title":"PRISMA 2020 Statement & Checklists","organization":"PRISMA Statement","category":"Systematic Reviews","description":"Official 27-item reporting checklist and flow diagram resources for designing, conducting, and reporting systematic reviews and meta-analyses.","url":"https://www.prisma-statement.org/","sort_order":2},{"legacy_id":"res-consort","title":"CONSORT & SPIRIT Reporting Guidelines","organization":"CONSORT-SPIRIT","category":"Clinical Trials","description":"Evidence-based minimum reporting standards for randomized controlled trials (CONSORT) and clinical trial protocols (SPIRIT).","url":"https://www.consort-spirit.org/","sort_order":3},{"legacy_id":"res-strobe","title":"STROBE Observational Study Checklists","organization":"STROBE Initiative","category":"Observational Studies","description":"Strengthening the Reporting of Observational Studies in Epidemiology: official checklists for cohort, case-control, and cross-sectional designs.","url":"https://www.strobe-statement.org/","sort_order":4},{"legacy_id":"res-amstar-2","title":"AMSTAR 2 Appraisal Tool","organization":"AMSTAR","category":"Systematic Reviews","description":"Validated 16-domain critical appraisal instrument for evaluating systematic reviews that include randomised and non-randomised healthcare studies.","url":"https://amstar.ca/index.php","sort_order":5}]$seed$::jsonb)
  as x(legacy_id text, title text, organization text, category text, description text, url text, sort_order int)
on conflict (legacy_id) do nothing;
